#!/usr/bin/env python#!/usr/bin/env python3# -*- coding: utf-8 -*-"""periodicity_QC_visualiser.py  ·  v2025-07-16===========================================QC panels for birdsong detectors – now with clearer highlighting.Colours-------Yellow (α = 0.45, drawn last) : periodicity_detected_song_timesPink   (α = 0.25)              : amplitude_detected_song_timesBlue   (α = 0.25)              : wiener_detected_song_timesRed  --                        : dashed file boundary"""from __future__ import annotationsimport argparseimport jsonfrom pathlib import Pathimport numpy as npimport matplotlib.pyplot as pltimport matplotlib.patches as mpatchesimport soundfile as sffrom scipy.signal import spectrogram# Seconds shown per timeline rowROW_DUR = 10.0# ───────────────────────── small helpers ─────────────────────────def _draw_segment(ax, audio: np.ndarray, sr: int, offset: float, dur: float, *, vmin: float = -90, vmax: float = -20) -> None:    """Draw a spectrogram of `audio` (already sliced for this segment)."""    if dur <= 0 or audio.size == 0:        return    # Choose window sizes proportional to SR, but keep your original defaults for 44.1k    nperseg = 1024 if sr >= 32000 else 512    noverlap = nperseg // 2    f, t, S = spectrogram(        audio,        fs=sr,        nperseg=nperseg,        noverlap=noverlap,        scaling="spectrum",        mode="magnitude",    )    S_db = 20.0 * np.log10(S + 1e-12)    ax.pcolormesh(offset + t, f, S_db, shading="auto", cmap="gray_r", vmin=vmin, vmax=vmax)def _highlight(ax, spans, pane_offset: float, seg_dur: float, *, colour: str, alpha: float, zorder: int) -> None:    """Overlay translucent rectangles for spans that intersect this segment."""    if not spans:        return    for s, e in spans:        if e <= 0 or s >= seg_dur:            continue        ax.axvspan(            pane_offset + max(s, 0.0),            pane_offset + min(e, seg_dur),            color=colour,            alpha=alpha,            zorder=zorder,        )def _save_legend(output_dir: Path) -> None:    fig, ax = plt.subplots(figsize=(4, 2))    ax.axis("off")    handles = [        mpatches.Patch(color="yellow", alpha=0.45, label="Periodicity span"),        mpatches.Patch(color="pink", alpha=0.25, label="Amplitude span"),        mpatches.Patch(color="blue", alpha=0.25, label="Wiener-entropy span"),        plt.Line2D([0], [0], color="red", lw=2, ls="--", label="File boundary"),    ]    ax.legend(handles=handles, frameon=False, loc="center")    out = output_dir / "periodicity_QC_key.png"    fig.savefig(out, dpi=300, bbox_inches="tight")    plt.close(fig)    print(f"[INFO] Saved {out}")# ───────────────────── main figure builder ─────────────────────def build_QC_panels(json_path: str | Path, output_dir: str | Path, *, sr: int = 44100, rows_per_fig: int = 6) -> None:    json_path, output_dir = Path(json_path), Path(output_dir)    output_dir.mkdir(parents=True, exist_ok=True)    with json_path.open() as f:        recs_all = json.load(f)    # Filter to recordings that actually have periodicity detections (non-empty)    def has_periodicity(r):        met = r.get("metrics", {})        spans = met.get("periodicity_detected_song_times", [])        return bool(spans)    recs = [r for r in recs_all if has_periodicity(r)]    if not recs:        print("[WARN] No recordings with periodicity detections found.")        return    legend_done = False    rec_idx = 0    rec_progress = 0.0    fig_no = 1    while rec_idx < len(recs):        fig, axes = plt.subplots(            rows_per_fig,            1,            figsize=(10, 2 * rows_per_fig),            sharex=True,            constrained_layout=True,        )        axes = np.atleast_1d(axes)        for ax in axes:            if rec_idx >= len(recs):                ax.axis("off")                continue            offset = 0.0            titles: list[str] = []            while offset < ROW_DUR and rec_idx < len(recs):                rec = recs[rec_idx]                met = rec.get("metrics", {})                # Robust fallbacks for missing fields                amp_spans = met.get("amplitude_detected_song_times", []) or []                wien_spans = met.get("wiener_detected_song_times", []) or []                per_spans = met.get("periodicity_detected_song_times", []) or []                wav_path = Path(rec.get("file_path", rec.get("file_name", "")))                if not wav_path or not wav_path.exists():                    print(f"[WARN] Missing or unreadable file path for record index {rec_idx}: {wav_path}")                    # Skip this record entirely                    rec_idx += 1                    rec_progress = 0.0                    continue                # Load clip once per recording                if rec_progress == 0.0:                    audio_full, sr_file = sf.read(wav_path)                    if audio_full.ndim > 1:                        audio_full = audio_full.mean(axis=1)                    if sr_file != sr:                        print(f"[WARN] {wav_path.name}: sr {sr_file} != requested {sr}; using {sr_file}")                        sr = sr_file  # adopt file SR                    # Compute fallback duration if missing                    duration_seconds = rec.get("duration_seconds")                    if duration_seconds is None or duration_seconds <= 0:                        duration_seconds = float(len(audio_full)) / float(sr)                        rec["duration_seconds"] = duration_seconds  # cache                remaining = float(rec["duration_seconds"]) - rec_progress                if remaining <= 0:                    # Defensive: treat as finished                    remaining = 0.0                seg_dur = min(remaining, ROW_DUR - offset)                if seg_dur <= 0:                    # No space left in this row                    break                # slice audio                start_samp = int(round(rec_progress * sr))                end_samp = start_samp + int(round(seg_dur * sr))                seg_audio = audio_full[start_samp:end_samp]                # Draw spectrogram                _draw_segment(ax, seg_audio, sr, offset, seg_dur)                # Shift spans into this segment's local time                shift = rec_progress                _highlight(ax, [(s - shift, e - shift) for s, e in amp_spans], offset, seg_dur, colour="pink", alpha=0.25, zorder=4)                _highlight(ax, [(s - shift, e - shift) for s, e in wien_spans], offset, seg_dur, colour="blue", alpha=0.25, zorder=5)                _highlight(ax, [(s - shift, e - shift) for s, e in per_spans], offset, seg_dur, colour="yellow", alpha=0.45, zorder=6)                # Advance counters                rec_progress += seg_dur                offset += seg_dur                # If the record is finished, draw a boundary and move to next                finished = abs(rec_progress - float(rec["duration_seconds"])) < 1e-6 or rec_progress >= float(rec["duration_seconds"])                if finished:                    ax.axvline(offset, color="red", ls="--", lw=1.0, zorder=7)                    titles.append(wav_path.name)                    rec_idx += 1                    rec_progress = 0.0            ax.set_xlim(0, ROW_DUR)            ax.set_ylim(0, 10_000)            ax.set_yticks([0, 2500, 5000, 7500, 10_000])            ax.set_ylabel("Freq [Hz]")            ax.tick_params(labelsize=8)            if titles:                ax.set_title(" + ".join(titles), fontsize=9, pad=4)        axes[-1].set_xlabel("Time [s]")        fig.suptitle(f"Periodicity QC panel {fig_no}", fontsize=12)        out_png = output_dir / f"periodicity_QC_panel_{fig_no:03d}.png"        fig.savefig(out_png, dpi=300)        plt.close(fig)        print(f"[INFO] Saved {out_png}")        if not legend_done:            _save_legend(output_dir)            legend_done = True        fig_no += 1# ────────────────────────── CLI entry ──────────────────────────if __name__ == "__main__":    ap = argparse.ArgumentParser(description="Visual QC for periodicity song detector.")    ap.add_argument("--json_path", required=True, type=str, help="Path to *_detected_song_intervals.json or equivalent JSON list.")    ap.add_argument("--output_dir", required=True, type=str, help="Directory to save QC panels and legend.")    ap.add_argument("--sr", default=44100, type=int, help="Requested sample rate; if the file differs, the file's SR is used.")    ap.add_argument(        "--rows",        default=6,        type=int,        dest="rows_per_fig",        help="Rows (timeline strips) per figure.",    )    args = ap.parse_args()    build_QC_panels(args.json_path, args.output_dir, sr=args.sr, rows_per_fig=args.rows_per_fig)"""    python periodicity_QC_visualiser.py \      --json_path "/path/to/USA5288_detected_song_intervals.json" \      --output_dir "/path/to/figures/periodicity_qc" \      --sr 44100 \      --rows 6        """#json_path = "/Users/mirandahulsey-vincent/Documents/allPythonCode/BYOD_class_clean/data_inputs/USA5510_unsegmented_songs/55_subsample_detected_song_intervals.json"#output_dir = "/Users/mirandahulsey-vincent/Documents/allPythonCode/BYOD_class_clean/data_inputs/USA5510_unsegmented_songs/55_subsample_detected_song_qc_panels"#build_QC_panels(json_path, output_dir,sr=44100,rows_per_fig=6)